import{z as i,x as l,o as t,c as d,q as s,j as A,D as e,d as r,s as o,S as B,b as E}from"./chunks/framework.C8m1ZpeB.js";const x=JSON.parse('{"title":"Raft","description":"","frontmatter":{"title":"Raft","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/raft.md","filePath":"cs/raft.md","lastUpdated":1791413859000}'),p={name:"cs/raft.md"};function C(m,a,D,f,u,h){const n=l("Mermaid");return t(),d("div",null,[a[2]||(a[2]=s('<h1 id="raft" tabindex="-1">Raft <a class="header-anchor" href="#raft" aria-label="Permalink to &quot;Raft&quot;">​</a></h1><div class="epigraph"><p>为可理解性重铸 Multi-Paxos：任期、日志匹配、只有最新日志者能当选。安全规则写进状态机，减少「议会」歧义。</p><footer>—— 据 Ongaro and Ousterhout, In Search of an Understandable Consensus Algorithm, USENIX ATC 2014 整理</footer></div><p>上一课<a href="/cs/multi-paxos">Multi-Paxos</a>已是稳定主 + 日志。缺口是<strong>实现者仍把 Paxos 理解岔</strong>：日志空洞、谁能当选、提交规则。Raft 用更严的约束换更少的合法交错。本课不重证多数派相交。后课成员变更与快照是论文后半，本课只到单配置日志。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>状态：Follower / Candidate / Leader。超时无心跳则竞选：自增 term，请求投票。投票：至多一票每任期；候选人日志必须至少与投票者（收到 RequestVote 的节点）一样新：比较两者最后条目的 term，term 相同再比 index。当选后 AppendEntries 复制，心跳是空追加。提交：当前任期条目在多数派出现才提交；借此避免论文里讨论的旧任期条目陷阱。</p><p>缺口：日志匹配性质——若两日志同一 index 同一 term，则该 index 及之前完全相同。AppendEntries 带前驱 index/term，不一致则拒绝并回退。比「每槽独立 Paxos」更少空洞玩法。</p><p><span class="marginnote">ATC 2014 与博士论文给出证明与 TLA+。本课不搬完整不变式表，后课 TLA+ 会回到 Raft 规格。</span></p><p><span class="marginnote">term（任期）就是「第几届领导班子」的编号：每次选举自增 1，节点只认任期不小于自己的消息。旧领导者网络分区恢复后带着过期任期回来，别人一看编号旧就直接拒绝——这个编号就是防「僵尸领导」的疫苗，也是全文比较日志新旧的第一把尺子。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>客户端只打领导者。跟随者拒绝写。读：线性一致要用 read index 或租约，论文实现常先给宽松读——规格上要分开。持久化：currentTerm、votedFor、日志条目在应答 RPC 前要上盘（崩溃恢复模型）。</p>',10)),(t(),A(B,null,{default:e(()=>[o(n,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20TO%5B%22%E9%80%89%E4%B8%BE%E8%B6%85%E6%97%B6%22%5D%20--%3E%20CAND%5B%22%E5%80%99%E9%80%89%E4%BA%BA%22%5D%0A%20%20CAND%20--%3E%20VOTE%5B%22%E5%A4%9A%E6%95%B0%E6%B4%BE%E6%8A%95%E7%A5%A8%22%5D%0A%20%20VOTE%20--%3E%20LED%5B%22%E9%A2%86%E5%AF%BC%E8%80%85%22%5D%0A%20%20LED%20--%3E%20AE%5B%22AppendEntries%22%5D%0A%20%20AE%20--%3E%20COMM%5B%22%E5%BD%93%E5%89%8D%E4%BB%BB%E6%9C%9F%E5%A4%9A%E6%95%B0%E6%B4%BE%20%E2%87%92%20%E6%8F%90%E4%BA%A4%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[r(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=E("p",null,[E("span",{class:"marginnote"},"多数派给个具体数：5 台节点里，一条日志要被 3 台写入才算提交。为什么是 3？任何两个「3 台小组」至少重叠 1 台——正是这个重叠保证两位领导者的日志必有公共前缀，旧值不会被新值悄悄盖掉。若 5 台里 2 台失联，剩余 3 台仍凑足多数派，系统照常工作；失联 3 台则宁可停止服务也不写坏数据。")],-1)),a[4]||(a[4]=E("p",null,"与 Paxos 编号：term 即 ballot。与检测器：超时实现 \\(\\Diamond\\) 类怀疑，误选举破坏活不破坏安全（旧领导者的 AppendEntries 因 term 小被拒）。",-1)),a[5]||(a[5]=E("h2",{id:"机制",tabindex:"-1"},[r("机制 "),E("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[6]||(a[6]=E("p",null,"「只有足够新的日志能当选」让领导者上任时不必从接受者那里搜集所有槽的已接受值再对齐——跟随者将被强制对齐到领导者日志（可能丢掉未提交尾部）。这是相对经典 Paxos 的实现选择：更简单，未提交条目可能被覆盖，客户端须重试。",-1)),(t(),A(B,null,{default:e(()=>[o(n,{id:"mermaid-41",class:"mermaid",graph:"flowchart%20TD%0A%20%20LEAD%5B%22%E9%A2%86%E5%AF%BC%E8%80%85%E5%8F%91%20AppendEntries%3Cbr%2F%3E%E5%B8%A6%E5%89%8D%E9%A9%B1%20index%20%2F%20term%22%5D%20--%3E%20CHK%7B%22%E8%B7%9F%E9%9A%8F%E8%80%85%E6%9C%AC%E5%9C%B0%E8%AF%A5%E4%BD%8D%E7%BD%AE%EF%BC%9Cbr%2F%EF%BC%9Eterm%20%E4%B8%80%E8%87%B4%EF%BC%9F%22%7D%0A%20%20CHK%20--%3E%7C%22%E4%B8%80%E8%87%B4%22%7C%20APP%5B%22%E6%8E%A5%E5%8F%97%E5%B9%B6%E8%BF%BD%E5%8A%A0%E6%96%B0%E6%9D%A1%E7%9B%AE%22%5D%0A%20%20CHK%20--%3E%7C%22%E4%B8%8D%E4%B8%80%E8%87%B4%EF%BC%9A%E6%8B%92%E7%BB%9D%22%7C%20BACK%5B%22%E8%B7%9F%E9%9A%8F%E8%80%85%E5%9B%9E%E6%8A%A5%E5%86%B2%E7%AA%81%E4%BD%8D%E7%BD%AE%3Cbr%2F%3E%E9%A2%86%E5%AF%BC%E8%80%85%E5%90%91%E5%89%8D%E5%9B%9E%E9%80%80%E5%86%8D%E8%AF%95%22%5D%0A%20%20BACK%20--%3E%20CHK%0A%20%20APP%20--%3E%20MORE%5B%22%E7%BB%A7%E7%BB%AD%E5%A4%8D%E5%88%B6%E5%90%8E%E7%BB%AD%E6%9D%A1%E7%9B%AE%22%5D%0A%20%20MORE%20--%3E%20MATCH%5B%22%E6%97%A5%E5%BF%97%E5%8C%B9%E9%85%8D%E6%80%A7%E8%B4%A8%E6%88%90%E7%AB%8B%EF%BC%9A%3Cbr%2F%3E%E5%90%8C%20index%20%E5%90%8C%20term%20%E2%87%92%20%E5%89%8D%E7%BC%80%E5%85%A8%E5%90%8C%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[r(" Loading... ",-1)])]),_:1})),a[7]||(a[7]=s('<p>本课不把 etcd 源码当规范。也不把 Raft 写成拜占庭协议。随机选举超时减脑裂竞选，是活性工程，不是安全。</p><p><span class="marginnote">随机选举超时就是让每台机器在 150-300 毫秒这样的区间里各自掷一个随机数「多等一会儿再竞选」：大家错峰起跑，避免同时起哄、反复平票。注意这只关乎效率——就算随机撞车、多选几轮，损失的也只是切换时间，不破坏已提交数据的安全。</span></p><p>与<a href="/cs/flp-impossibility">FLP</a>：选举超时 = 部分同步。关掉超时，Raft 也不终止。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写联合共识成员变更、不写快照 RPC。不引入 PreVote 作为必选项（常见工程补丁，点名）。后课专门补成员与快照。Zab、VR 是亲戚，稍后对照，不在本课展开。</p><p>可理解性是设计目标：更少的合法状态，代价是更严的回退与覆盖未提交尾。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>任期 + 日志匹配 + 最新日志当选。</li><li>只提交当前任期的多数派条目。</li><li>安全不靠超时；活性靠超时与随机化。</li><li>出处：Ongaro and Ousterhout, USENIX ATC 2014。</li></ul>',8))])}const P=i(p,[["render",C]]);export{x as __pageData,P as default};
